    else {
      data[locale].sections.forEach((s, i) => {
        if (!s.heading) issues.push(\`\${locale}.sections[\${i}].heading missing\`);
        if (!s.body) issues.push(\`\${locale}.sections[\${i}].body missing\`);
      });
    }
    if (!data[locale].variations || data[locale].variations.length === 0) issues.push(\`\${locale}.variations empty\`);
    else {
      data[locale].variations.forEach((v, i) => {
        if (!v.heading) issues.push(\`\${locale}.variations[\${i}].heading missing\`);
        if (!v.body) issues.push(\`\${locale}.variations[\${i}].body missing\`);
      });
    }
    if (!data[locale].faqs || data[locale].faqs.length < 5) issues.push(\`\${locale}.faqs <5 (\${data[locale].faqs?.length})\`);
    else {
      data[locale].faqs.forEach((f, i) => {
        if (!f.question) issues.push(\`\${locale}.faqs[\${i}].question missing\`);
        if (!f.answer) issues.push(\`\${locale}.faqs[\${i}].answer missing\`);
